// Extract summary data from WayinVideo
const summaryData = $('4. WayinVideo — Get Summary Results').item.json.data;

const summary = summaryData.summary || '';
const highlights = Array.isArray(summaryData.highlights)
  ? summaryData.highlights.map((h, i) => `${i + 1}. ${h.desc}`).join('\n')
  : '';
const tags = Array.isArray(summaryData.tags)
  ? summaryData.tags.join(', ')
  : '';

// Get form data
const courseTitle = $('1. Form — Course Video + Details').item.json['Course Title'];
const moduleTitle = $('1. Form — Course Video + Details').item.json['Module / Lecture Title'];
const assignTo = $('1. Form — Course Video + Details').item.json['Assign Tasks To'];
const dueDate = $('1. Form — Course Video + Details').item.json['Task Due Date'];
const priority = $('1. Form — Course Video + Details').item.json['Task Priority'];
const videoUrl = $('1. Form — Course Video + Details').item.json['Course Video URL'];

// Map priority to ClickUp priority number
const priorityMap = {
  'urgent': 1,
  'high': 2,
  'normal': 3,
  'low': 4
};
const priorityNumber = priorityMap[priority.toLowerCase()] || 3;

// Convert due date to Unix timestamp (milliseconds)
const dueDateTimestamp = new Date(dueDate).getTime();

return [{
  json: {
    summary,
    highlights,
    tags,
    courseTitle,
    moduleTitle,
    assignTo,
    dueDate,
    dueDateTimestamp,
    priority,
    priorityNumber,
    videoUrl
  }
}];

// Parse AI output — extract JSON array of tasks
const output = $input.first().json.output || '';

let tasks = [];
try {
  const cleaned = output
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const match = cleaned.match(/\[\s*\{[\s\S]*\}\s*\]/);
  if (match) {
    tasks = JSON.parse(match[0]);
  } else {
    tasks = JSON.parse(cleaned);
  }
} catch (e) {
  throw new Error('Could not parse tasks from AI output: ' + output.substring(0, 300));
}

if (!Array.isArray(tasks) || tasks.length === 0) {
  throw new Error('No tasks extracted from AI output.');
}

// Get module data
const courseTitle = $('7. Code — Extract Summary Data').item.json.courseTitle;
const moduleTitle = $('7. Code — Extract Summary Data').item.json.moduleTitle;
const assignTo = $('7. Code — Extract Summary Data').item.json.assignTo;
const dueDateTimestamp = $('7. Code — Extract Summary Data').item.json.dueDateTimestamp;
const priorityNumber = $('7. Code — Extract Summary Data').item.json.priorityNumber;
const videoUrl = $('7. Code — Extract Summary Data').item.json.videoUrl;
const summary = $('7. Code — Extract Summary Data').item.json.summary;

// Return one item per task
return tasks.map(task => ({
  json: {
    taskNumber: task.task_number || 0,
    taskTitle: `[${courseTitle}] ${task.task_title || 'Learning Task'}`,
    taskDescription: task.task_description || '',
    taskType: task.task_type || 'Practice',
    estimatedMinutes: task.estimated_minutes || 30,
    checklistItems: Array.isArray(task.checklist_items) ? task.checklist_items : [],
    courseTitle,
    moduleTitle,
    assignTo,
    dueDateTimestamp,
    priorityNumber,
    videoUrl,
    summary,
    totalTasks: tasks.length
  }
}));
